diff --git a/src/sanitize-svg.js b/src/sanitize-svg.js
new file mode 100644
index 0000000..4d9a839
--- /dev/null
+++ b/src/sanitize-svg.js
@@ -0,0 +1,55 @@
+const unsafeElements = new Set([
+    'script',
+    'foreignobject',
+    'iframe',
+    'object',
+    'embed'
+]);
+
+const emptySvg = '<svg xmlns="http://www.w3.org/2000/svg"/>';
+
+const isUnsafeUrl = value => {
+    const normalized = value.replace(/[\u0000-\u0020]/g, '').toLowerCase();
+    return normalized.indexOf('javascript:') === 0 ||
+        normalized.indexOf('vbscript:') === 0;
+};
+
+/**
+ * Remove executable content from untrusted SVG input before it is rendered.
+ * @param {string} svgString SVG source
+ * @returns {string} sanitized SVG source
+ */
+const sanitizeSvg = svgString => {
+    const document = new DOMParser().parseFromString(svgString, 'image/svg+xml');
+
+    if (!document.documentElement ||
+        document.documentElement.localName !== 'svg' ||
+        document.documentElement.localName === 'parsererror') {
+        return emptySvg;
+    }
+
+    const elements = document.getElementsByTagName('*');
+    for (let i = elements.length - 1; i >= 0; i--) {
+        const element = elements[i];
+        const elementName = element.localName.toLowerCase();
+
+        if (unsafeElements.has(elementName)) {
+            element.parentNode.removeChild(element);
+            continue;
+        }
+
+        for (let j = element.attributes.length - 1; j >= 0; j--) {
+            const attribute = element.attributes[j];
+            const attributeName = attribute.name.toLowerCase();
+
+            if (attributeName.indexOf('on') === 0 ||
+                ((attributeName === 'href' || attributeName === 'xlink:href') &&
+                    isUnsafeUrl(attribute.value))) {
+                element.removeAttribute(attribute.name);
+            }
+        }
+    }
+
+    return new XMLSerializer().serializeToString(document.documentElement);
+};
+
+module.exports = sanitizeSvg;

