+'use strict';
+
+var url = require('url');
+
+function isSameOrigin(req, value) {
+  var origin = url.parse(value);
+  var host = req.headers.host;
+
+  return origin.protocol
+    && origin.host
+    && host
+    && origin.host.toLowerCase() === host.toLowerCase();
+}
+
+module.exports = function(req, res, next) {
+  var method = req.method;
+
+  // CGI GET requests are used to retrieve UI data. Mutating CGI APIs use
+  // unsafe HTTP methods and must originate from the Web UI.
+  if (method === 'GET' || method === 'HEAD' || method === 'OPTIONS') {
+    return next();
+  }
+
+  var origin = req.headers.origin;
+  if (origin) {
+    if (isSameOrigin(req, origin)) {
+      return next();
+    }
+  } else {
+    var referer = req.headers.referer;
+    if (referer && isSameOrigin(req, referer)) {
+      return next();
+    }
+
+    // XMLHttpRequest is a non-simple request header and therefore cannot be
+    // supplied by a cross-origin form submission.
+    if (req.headers['x-requested-with'] === 'XMLHttpRequest') {
+      return next();
+    }
+  }
+
+  res.statusCode = 403;
+  res.end('Forbidden');
+};
